package("nexus-ngcpp-proxy")
    set_homepage("https://github.com/ngcpp/proxy")
    set_description("Pinned ngcpp/proxy runtime polymorphism headers")
    set_license("MIT")
    set_kind("library", {headeronly = true})
    add_urls(os.getenv("NEXUS_NGCPP_PROXY_SOURCE") or "https://github.com/ngcpp/proxy.git")
    add_versions("0.1.0", "9d9749d63766cdd9affb5ea7953237e38ce5ab63")
    on_install(function (package)
        os.cp("include/*", package:installdir("include"))
        os.cp("LICENSE", package:installdir("share/licenses/nexus-ngcpp-proxy"))
    end)
    on_test(function (package)
        assert(package:has_cxxincludes("proxy/proxy.h", {configs = {languages = "c++26"}}))
    end)
package_end()
